<div class="cards">
<div class="card"><span>Sản phẩm có tồn</span><strong><?= number_format($summary['stocked_products']) ?></strong><small>trong <?= number_format($productCount) ?> sản phẩm</small></div>
<div class="card warning"><span>Chạm / dưới ngưỡng</span><strong><?= number_format($summary['low_stock_count']) ?></strong><small>Gồm hàng chưa có tồn</small></div>
