<?php if (can('documents.view')): ?><div class="panel table-scroll"><h2>Phiếu gần đây</h2><table class="table"><thead><tr><th>Số phiếu</th><th>Loại</th><th>Ngày chứng từ</th><th>Đối tác</th><th>Trạng thái</th></tr></thead><tbody><?php foreach ($summary['recent_documents'] as $document): ?><tr><td><a href="/documents/show?id=<?= e($document['id']) ?>"><?= e($document['number']) ?></a></td><td><?= document_type_label($document['document_type']) ?></td><td><?= e($document['document_date']) ?></td><td><?= e($document['partner_name']) ?></td><td><span class="badge <?= $document['status']==='posted'?'success':'muted' ?>"><?= document_status_label($document['status']) ?></span></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?>
